package com.agencytrip.agencytripapi.infrastructure.adapter.out.persistence.entity;
import jakarta.persistence.*; import lombok.*; import java.math.BigDecimal; import java.time.LocalDateTime;
@Entity @Table(name="reservas") @Getter @Setter @NoArgsConstructor public class ReservationEntity { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) @Column(name="id_reserva") private Integer idReserva; @Column(name="id_usuario") private Integer idUsuario; @Column(name="id_paquete") private Integer idPaquete; @Column(name="fecha_reserva") private LocalDateTime fechaReserva; @Column(name="cantidad_personas") private int cantidadPersonas; @Column(name="precio_total") private BigDecimal precioTotal; private String estado; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="id_usuario",insertable=false,updatable=false) private UserEntity usuario; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="id_paquete",insertable=false,updatable=false) private PackageEntity paquete; }
